import math

def is_power_of_5(x):
    if x <= 0:
        return False
    if x == 1:
        return True, 0

    k = 0
    temp_x = x
    while temp_x > 1 and temp_x % 5 == 0:
        temp_x //= 5
        k += 1

    if temp_x == 1:
        return True, k
    else:
        return False, -1

results = {}
for n in range(3, 26):
    X = (2**n) - 3
    is_power, k = is_power_of_5(X)

    if is_power:
        results[n] = k

print("Found solutions (n: k):", results)

def is_power_of_five(N):
    if N <= 0:
        return False
    if N == 1: # 5^0 = 1, but since n>=3, 2^n-3 >= 5, so k>=1.
        return False
    while N > 1 and N % 5 == 0:
        N //= 5
    return N == 1

solutions = []
for n in range(3, 31):
    val = 2**n - 3
    if is_power_of_five(val):
        k = 0
        temp_val = val
        while temp_val > 1:
            temp_val //= 5
            k += 1
        solutions.append((n, k))

print("Solutions (n, k) found for n <= 30:", solutions)

def is_power_of_5(N):
    """Checks if N is a power of 5 (5^k for some non-negative integer k)."""
    if N <= 0:
        return False
    if N == 1:
        return True # 5^0

    while N % 5 == 0:
        N //= 5

    return N == 1

solutions = []
# Search for odd n from 9 up to 101.
# Previous solutions were n=3, n=7. We start checking from n=9.
for n in range(9, 102, 2):
    X = 2**n - 3
    if is_power_of_5(X):
        # Find k such that X = 5^k
        k = 0
        temp_X = X
        while temp_X > 1:
            temp_X //= 5
            k += 1
        solutions.append((n, k))

print(f"Found solutions (n, k) for odd n up to 101: {solutions}")
